import sys


def main():
    deps = {}
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        name, _, rest = line.partition(":")
        name = name.strip()
        deps.setdefault(name, []).extend([d.strip() for d in rest.split()])

    done = set()
    order = []

    def visit(task):
        if task in done:
            return
        done.add(task)
        for d in sorted(deps.get(task, [])):
            visit(d)
        order.append(task)

    remaining = set(deps.keys())
    while remaining:
        no_deps = [task for task in remaining if all(d in done for d in deps.get(task, []))]
        if not no_deps:
            print("CYCLE: " + " ".join(sorted(remaining)))
            return
        task = min(no_deps)
        visit(task)
        remaining.discard(task)

    for task in order:
        print(task)


if __name__ == "__main__":
    main()
